const body = $input.first().json.body || $input.first().json;

const fields = body.data?.fields || [];

let startupName = '';
let problem = '';
let targetAudience = '';
let budget = '';
let founderName = '';
let founderEmail = '';

for (const field of fields) {
  const label = (field.label || '').toLowerCase();
  const value = field.value || '';
  if (label.includes('startup') || label.includes('name')) startupName = value;
  if (label.includes('problem')) problem = value;
  if (label.includes('audience') || label.includes('customer')) targetAudience = value;
  if (label.includes('budget')) budget = value;
  if (label.includes('founder') || label.includes('your name')) founderName = value;
  if (label.includes('email')) founderEmail = value;
}

return [{
  json: {
    startupName: startupName || 'My Startup',
    problem: problem || 'Not specified',
    targetAudience: targetAudience || 'General public',
    budget: budget || 'Not specified',
    founderName: founderName || 'Founder',
    founderEmail: founderEmail || '',
    submittedAt: new Date().toISOString()
  }
}];

const tallyData = $('Parse Tally Data').item.json;

// OpenRouter response parse karna
function parseAgent(nodeName) {
  try {
    const raw = $(nodeName).item.json;
    // OpenRouter format
    const content = raw?.choices?.[0]?.message?.content 
      || raw?.message?.content 
      || raw?.content 
      || raw?.text 
      || '{}';
    return JSON.parse(content.replace(/```json|```/g, '').trim());
  } catch(e) {
    return {};
  }
}

const planner  = parseAgent('AI Startup Planner Agent');
const market   = parseAgent('Market Research Agent');
const pricing  = parseAgent('Pricing Agent');
const marketing = parseAgent('Marketing Agent');

return [{
  json: {
    startupName: tallyData.startupName,
    founderName: tallyData.founderName,
    founderEmail: tallyData.founderEmail,
    submittedAt: tallyData.submittedAt,
    problem: tallyData.problem,
    targetAudience: tallyData.targetAudience,
    budget: tallyData.budget,

    // Planner
    executiveSummary: planner.executiveSummary || '',
    solution: planner.solution || '',
    businessModel: planner.businessModel || '',
    uniqueValueProposition: planner.uniqueValueProposition || '',
    revenueStreams: planner.revenueStreams || '',

    // Market Research
    marketSize: market.marketSize || '',
    topCompetitors: Array.isArray(market.topCompetitors) 
      ? market.topCompetitors.join(', ') 
      : (market.topCompetitors || ''),
    marketTrends: market.marketTrends || '',
    entryStrategy: market.entryStrategy || '',

    // Pricing
    pricingModel: pricing.pricingModel || '',
    recommendedPrice: pricing.recommendedPrice || '',
    revenueProjection: pricing.revenueProjection12Months || '',

    // Marketing
    brandPositioning: marketing.brandPositioning || '',
    launchCampaign: marketing.launchCampaign || '',
    month1Actions: marketing.month1Actions || '',
    month3Goals: marketing.month3Goals || '',

    processedAt: new Date().toISOString()
  }
}];

